terrainY.runtimeFunction:
(x, z) => {
    const base = -sphereDrop(x, z) + 0.05;
    if (!footprintSpec) return base + bump(x, z) * terrainHeightScale;
    // 向边缘连续压低丘陵，边界自然落回星球表面，不形成垂直切口。
    const edgeKeep = 1 - smoothstepJS(0.58, 1.0, footprintDistance(x, z));
    return base + bump(x, z) * edgeKeep * terrainHeightScale;
  }

59479d68-f06e-432e-9b9b-788e4a02cbb8.onBeforeCompile:
(shader) => {
      shader.vertexShader = shader.vertexShader
        .replace("void main() {", "varying vec3 vBrushPos;\nvoid main() {")
        .replace(
          "#include <begin_vertex>",
          `#include <begin_vertex>
\tvBrushPos = position;
\tfloat tmHash = fract(sin(dot(position.xyz, vec3(12.9898, 78.233, 37.719))) * 43758.5453);
\ttransformed += normal * (${thickness.toFixed(4)} * (0.65 + 0.6 * tmHash));`
        );
      shader.fragmentShader = shader.fragmentShader
        .replace("void main() {", "varying vec3 vBrushPos;\nvoid main() {")
        .replace(
          "#include <clipping_planes_fragment>",
          `#include <clipping_planes_fragment>
\tfloat tmDry = fract(sin(dot(floor(vBrushPos * 36.0).xy, vec2(12.9898, 78.233))) * 43758.5453);
\tif (tmDry < ${dry.toFixed(3)}) discard;`
        );
    }
